export const main = (): i32 => {
  const t: Suite = new Suite("rfc8017-rsassa-pss-sha256");
  let ran: string = "";
  ran = `${ran}${clause_P_KEY_PUBLIC(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_KEY_WINDOW(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_KEY_FLIP(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_KEY_CRT(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_KEY_VERSION(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_KEY_OTHER_PRIMES(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_RAW_RANGE(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_RAW_FIXED(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_RAW_KNOWN(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_PSS_KNOWN(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_ROUNDTRIP(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_LENGTH(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_SALT_LENGTH(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_SALT_DERIVED(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_SALTED(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_SALT_DISTINCT(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_EM_ROOM(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_TAMPER_MSG(t) ? "1" : "0"}`;
  ran = `${ran}${clause_P_TAMPER_SIG(t) ? "1" : "0"}`;
  const code: i32 = t.done();
  const nonce: string = toI32(process.argv.length) > 1 ? process.argv[1] : "-";
  console.log(`vector-done ${nonce} ${ran}`);
  return code;
};
